import { type ImmutableObject } from 'seamless-immutable';
import { type ModalStates } from '@types/divi__modal';
import { type Events, type KeyboardShortcuts, type ModuleType, type RightClickOptions } from '@divi/types';
export interface Log {
    actionType: string;
    trigger: string;
    payload: Record<string, any>;
}
export type Logs = Log[];
export interface ModalLoggerProps {
    editPost: Logs;
    events: Logs;
}
export type Props = ModalStates & ModalLoggerProps;
export interface KeyboardPanelProps {
    pressedKeys: KeyboardShortcuts.Store.ImmutableState['pressedKeys'];
    current: ImmutableObject<KeyboardShortcuts.Shortcut.Item>;
}
export interface PanelDraggableModuleProps {
    selectedModules: Events.Selected.Modules;
    selectedModulesLowest: ModuleType;
    draggingStatus: boolean;
    draggedModules: Events.Store.ImmutableState['draggedModules'];
    cursorPosition: Events.Cursor.Position;
    hoveredModule: Events.Hovered.Module;
}
export interface PanelRightClickOptionsProps {
    storeState: RightClickOptions.Store.ImmutableState;
}
export interface PanelAppViewProps {
    activeViewName: string;
    activeView: {
        width: string;
        height: string;
        label: string;
        icon: string;
    };
    topWindow: {
        width: number;
        height: number;
    };
    appWindow: {
        width: number;
        height: number;
    };
}
